with base as (select id, channel, starts_on, ends_on, discount_pct, round(discount_pct, 0) as discount_pct_rounded, case when discount_pct >= 0.33 then 'High' when discount_pct >= 0.09 then 'Medium' else 'Low' end as discount_pct_tier from promotions where channel is not null) select channel, id from base except select channel, id from promotions where month(starts_on) in (4, 6, 11)
